-- Map the legacy knowledge structure onto existing shared database binds.
-- The embedded payload contains structure plus one-way normalized identifiers only.
-- It never inserts legacy binds or removes database-only binds.
create table if not exists public.supportos_legacy_bind_mapping_report (
 report_key text primary key,
 run_id text not null,
 side text not null check (side in ('legacy', 'database')),
 legacy_bind_id text,
 database_bind_id text,
 status text not null check (status in ('matched', 'ambiguous', 'unmatched', 'db_only')),
 candidate_count integer not null default 0 check (candidate_count >= 0),
 candidate_ids jsonb not null default '[]'::jsonb,
 best_score bigint,
 target_category_id text,
 target_folder_id text,
 changed boolean not null default false,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);

create index if not exists supportos_legacy_bind_mapping_report_run_status_idx
on public.supportos_legacy_bind_mapping_report (run_id, status, side);

alter table public.supportos_legacy_bind_mapping_report enable row level security;

revoke all on table public.supportos_legacy_bind_mapping_report
from public, anon, authenticated;

grant select, insert, update on table public.supportos_legacy_bind_mapping_report
to service_role;

create or replace function pg_temp.supportos_normalize_legacy_text(value text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
 select lower(regexp_replace(trim(coalesce(value, '')), '[[:space:]]+', ' ', 'g'));
$function$;

