caabc45269348be00116242f60beb"],["p","8bc8df43948ca8e8603c861f6b3ea29b"],["c","98e413d2e551c661932c6b6a054b09b1"],["t","3d2c7020cbf04ae95953ec0ead85ad47"],["p","67938460d8a68f68b86652ddc0aee548"],["c","3315d8b0afbdafe1266b770961a22691"],["t","15f6ca9f7e553860fcd6e0a37c99ca82"]]},{"i":"bind-99e056c8-21cb-4395-bd4c-c92d1833dd4b","c":"category-20e0cc02-23d7-42cf-807b-c3dd40e804c2","f":"folder-0d7a2ca1-7d81-4c6e-98c7-5ccd8f45705f","x":[["p","6dfae313655e9a2e55343be6781e8a48"],["c","67bae106ecc6a24f68184038a13ad983"],["t","fe0bcfbb5e141d758c29a02daf1486af"],["p","4115bc5a9279d78f3412c729331fd86f"],["c","0dc544de30f3c7683517ea607e288ff1"],["t","eba5266b44ee5f68ee7983418b6a6f86"],["p","de9864e43c2e81032b4f1c916ad732bc"],["c","3e7a96b35d8f5ced81a498f2dc50809f"],["t","030e0c24729178ba75ad76a6edb29dcc"],["p","d45eeb3271fed00e417e2260afbe8db4"],["c","21a7902b2c0440cf4fbb46daa2b74bac"],["t","abdaf62de3165cde5d2d06ef36ca6c56"],["p","5385fb9aa04a394970f52a63f12c5410"],["c","d002f5b965ca09a16ca144ee96f1632f"],["t","4461d3e142c67e032d4003d75d327161"]]},{"i":"bind-52c190ad-d02a-445b-a187-d3a826a28aec","c":"category-20e0cc02-23d7-42cf-807b-c3dd40e804c2","f":"folder-0b5cca6e-3314-4355-b662-66f032b4ffdd","x":[["p","934078fc2a9ebd7c623648c0b6cfb593"],["c","200230284c8651c4b23eb1a5eadf2644"],["t","ac27d6477ac68771866155926dcc2ac1"],["p","25d4c1caef82cee9eb88553440c0fb5f"],["c","3412a461862352fcdc3e7284a996ad18"],["t","f387cddd091662ea7a21270de5ac43bc"],["p","773f1e1e55cc0db894fa5b4e8e3bef10"],["c","cd42def0ab4eab4e7571766808ea8e81"],["t","3e934ce8f084af681dee42820b170727"],["p","309ebce75d1fbd97774e96ecb73f3eb9"],["c","733520a106d34f6ca32239ca0f8de401"],["t","5de4a395d2baee9770483acb0cb56376"],["p","58aabfcf8b0539febaf0c44d222e555e"],["c","b53919cb521953019cc55448760dd8cb"],["t","18838f138a30c471cf4de1b92141d6e1"]]},{"i":"bind-853c741d-8e3b-40ce-8565-0fc035228513","c":"category-c6d02ac8-efc4-4952-b24d-b67f17e42ece","f":null,"x":[["p","5de74c6663ae109ddd674d96fee88286"],["c","e8b37d3587e48a8a95f93e06ad5f2e3f"],["t","80b1b632ea05209f566a2c20910ccffd"],["p","fade7a62c2fb5822446d97959bca9ca1"],["c","e1922f28702a5287799c77b4d6f00d06"],["t","78554ebe948f9e8c331ac4bb6027e3a5"],["p","851c5593795d25b0c5003b3af0109e52"],["c","5bf31f251d2443e1e64b7a16d99f27db"],["t","f56e3a3e0f17e8cfdc4bfed465e4dca6"],["p","d92b709132bc427158c98f53afc3568c"],["c","bed1231d8e6f69b3a4387a18bd1830ef"],["t","b64a3cb6a639b54290a61f3cdc4c112e"],["p","feecba6e8e95b7298851e5367b5085e5"],["c","92ce8e5def940f6979a774e01af787b0"],["t","1a8665fae9061d0ae270913a701b342b"]]},{"i":"bind-aad81e96-c403-4168-8f0e-3bcec9c9f3af","c":"category-07464f26-55ef-40f2-ba35-43a87cdc14db","f":"folder-f096d86f-12b2-421e-a9c8-d6f9c0d27d97","x":[["p","17a00d2c3dceb3a940decf1d7a596792"],["c","d917b9aaca209fda7bceaac73ed8f843"],["t","d917b9aaca209fda7bceaac73ed8f843"]]},{"i":"bind-a4324cea-97ac-47cb-89ac-aca1181ff32d","c":"category-20e0cc02-23d7-42cf-807b-c3dd40e804c2","f":null,"x":[["p","1b5913e54de77df952c582c9b0b58eab"],["c","c47ea0dd49be90ad100e0de0d713738c"],["t","127704b6e951c6c8cc334401004a5d6a"],["p","c1b889625afb9ee85d51b3a19f197472"],["c","e484831d26cb1c68457d3d9687279ced"],["t","1764bf0a428c94c04c4c6cda8aeb2d0a"],["p","dd07fbb613840a0b087a279db82d70e3"],["c","a5a30ea6b14005744ae5c39a5c9e4c0e"],["t","7d47782f7de9a390e909451260c8fa20"],["p","f6e74564fcd653971d920cc304eacf80"],["c","b71584ee004c9f0aa7716a755b72208d"],["t","1278b8a3a9884b8be28cd9119573600b"],["p","48546c1a8c3530c602b0f3f31f592d2f"],["c","18649916c32adb3ad99c5573e17bc040"],["t","8e2c4b83d5dd3ec809122fc57b82efb8"]]},{"i":"bind-0a2881b7-f446-4b92-85d2-af0c7d362913","c":"category-aedb1a02-13b7-4a24-b2da-60af508c51c1","f":null,"x":[["p","ba8416bca62c3c3a0f3fea769c897be4"],["c","2a13de1b82289979bb0771a5211e9149"],["t","8cc92b738c4c8228b060419984ac16bf"],["p","5bb802955ca8210481d7b8a804eec33d"],["c","6e0ae713f949e5ce2a075c2c53aa35eb"],["t","c8d5c55de1959cadad90b2bd26c15d0a"],["p","2e908ea1b88e5f86f46d72f604acba90"],["c","6006ac0904563e14fed5cb22a6cdd0a6"],["t","d63ca51595ebe99664553689f02a3634"],["p","a7ad44be00d2c2d8416c89666b320950"],["c","f5a01dc9824c24757306916cf03aff9e"],["t","0fec144805cf53305c47a452f7bff7fa"],["p","b63a8fd34f5657aaeb69470a8c121663"],["c","fcb5af71070e40acf3073065d86c9101"],["t","5dc4a9ea3f7eb6c3086005c903e10738"]]}]}$supportos_legacy_knowledge$::jsonb;
 mapping_run constant text := '20260925040616';
 binds_before bigint;
 binds_after bigint;
 categories_inserted integer;
 folders_inserted integer;
 matched_count integer;
 changed_count integer;
 legacy_summary jsonb;
 database_summary jsonb;
 ambiguous_report jsonb;
begin
 select count(*) into binds_before
 from public.supportos_binds;

 create temporary table legacy_bind_map (
  legacy_bind_id text primary key,
  category_id text not null,
  folder_id text,
  identifiers jsonb not null
 ) on commit drop;

 insert into legacy_bind_map (legacy_bind_id, category_id, folder_id, identifiers)
 select
  bind->>'i',
  bind->>'c',
  nullif(bind->>'f', ''),
  coalesce(bind->'x', '[]'::jsonb)
 from jsonb_array_elements(legacy_data->'b') bind
 where nullif(bind->>'i', '') is not null
  and nullif(bind->>'c', '') is not null;

 create temporary table legacy_identifiers on commit drop as
 select distinct
  legacy.legacy_bind_id,
  identifier->>0 as kind,
  identifier->>1 as identifier
 from legacy_bind_map legacy
 cross join lateral jsonb_array_elements(legacy.identifiers) identifier
 where identifier->>0 in ('p', 'c', 't')
  and length(identifier->>1) = 32;

 create index on legacy_identifiers (kind, identifier);
 create index on legacy_identifiers (legacy_bind_id);

 create temporary table database_identifiers on commit drop as
 with translations as (
  select
   bind.id as database_bind_id,
   lower(trim(translation->>'language')) as language,
   pg_temp.supportos_normalize_legacy_text(translation->>'title') as title,
   pg_temp.supportos_normalize_legacy_text(translation->>'content') as content
  from public.supportos_binds bind
  cross join lateral jsonb_array_elements(
   case
    when jsonb_typeof(bind.translations) = 'array' then bind.translations
    else '[]'::jsonb
   end
  ) translation
  where bind.owner_id is null
   and nullif(trim(translation->>'language'), '') is not null
 )
 select distinct database_bind_id, kind, identifier
 from (
  select
   database_bind_id,
   'p'::text as kind,
   md5(language || chr(31) || title || chr(31) || content) as identifier
  from translations
  where title <> '' and content <> ''
  union all
  select
   database_bind_id,
   'c'::text,
   md5(language || chr(31) || content)
  from translations
  where content <> ''
  union all
  select
   database_bind_id,
   't'::text,
   md5(language || chr(31) || title)
  from translations
  where title <> ''
 ) identifiers;

 create index on database_identifiers (kind, identifier);
 create index on database_identifiers (database_bind_id);

 create temporary table candidate_scores on commit drop as
 select
  legacy.legacy_bind_id,
  database.database_bind_id,
  count(*) filter (where legacy.kind = 'p')::integer as pair_matches,
  count(*) filter (where legacy.kind = 'c')::integer as content_matches,
  count(*) filter (where legacy.kind = 't')::integer as title_matches,
  (
   count(*) filter (where legacy.kind = 'p') * 1000000
   + count(*) filter (where legacy.kind = 'c') * 1000
   + count(*) filter (where legacy.kind = 't')
  )::bigint as score
 from legacy_identifiers legacy
 join database_identifiers database
  on database.kind = legacy.kind
  and database.identifier = legacy.identifier
 group by legacy.legacy_bind_id, database.database_bind_id;

 create index on candidate_scores (legacy_bind_id, score desc);
 create index on candidate_scores (database_bind_id, score desc);

 create temporary table resolved_matches on commit drop as
 with maxima as (
  select
   candidate.*,
   max(score) over (partition by legacy_bind_id) as legacy_best_score,
   max(score) over (partition by database_bind_id) as database_best_score
  from candidate_scores candidate
 ),
 reciprocal_best as (
  select *
  from maxima
  where score = legacy_best_score
   and score = database_best_score
 ),
 choices as (
  select
   reciprocal_best.*,
   count(*) over (partition by legacy_bind_id) as legacy_choice_count,
   count(*) over (partition by database_bind_id) as database_choice_count
  from reciprocal_best
 )
 select
  choices.legacy_bind_id,
  choices.database_bind_id,
  legacy.category_id,
  legacy.folder_id,
  choices.score
 from choices
 join legacy_bind_map legacy using (legacy_bind_id)
 where choices.legacy_choice_count = 1
  and choices.database_choice_count = 1;

 create unique index on resolved_matches (legacy_bind_id);
 create unique index on resolved_matches (database_bind_id);

 -- Persist the report before changing any bind category/folder.
 insert into public.supportos_legacy_bind_mapping_report (
  report_key, run_id, side, legacy_bind_id, database_bind_id, status,
  candidate_count, candidate_ids, best_score, target_category_id,
  target_folder_id, changed, created_at, updated_at
 )
 select
  mapping_run || ':legacy:' || legacy.legacy_bind_id,
  mapping_run,
  'legacy',
  legacy.legacy_bind_id,
  resolved.database_bind_id,
  case
   when resolved.database_bind_id is not null then 'matched'
   when candidates.candidate_count > 0 then 'ambiguous'
   else 'unmatched'
  end,
  coalesce(candidates.candidate_count, 0),
  coalesce(candidates.candidate_ids, '[]'::jsonb),
  candidates.best_score,
  legacy.category_id,
  legacy.folder_id,
  false,
  now(),
  now()
 from legacy_bind_map legacy
 left join resolved_matches resolved using (legacy_bind_id)
 left join lateral (
  select
   count(*)::integer as candidate_count,
   jsonb_agg(candidate.database_bind_id order by candidate.score desc, candidate.database_bind_id) as candidate_ids,
   max(candidate.score) as best_score
  from candidate_scores candidate
  where candidate.legacy_bind_id = legacy.legacy_bind_id
 ) candidates on true
 on conflict (report_key) do update set
  run_id = excluded.run_id,
  side = excluded.side,
  legacy_bind_id = excluded.legacy_bind_id,
  database_bind_id = excluded.database_bind_id,
  status = excluded.status,
  candidate_count = excluded.candidate_count,
  candidate_ids = excluded.candidate_ids,
  best_score = excluded.best_score,
  target_category_id = excluded.target_category_id,
  target_folder_id = excluded.target_folder_id,
  changed = false,
  updated_at = now();

 insert into public.supportos_legacy_bind_mapping_report (
  report_key, run_id, side, legacy_bind_id, database_bind_id, status,
  candidate_count, candidate_ids, best_score, target_category_id,
  target_folder_id, changed, created_at, updated_at
 )
 select
  mapping_run || ':database:' || bind.id,
  mapping_run,
  'database',
  resolved.legacy_bind_id,
  bind.id,
  case
   when resolved.legacy_bind_id is not null then 'matched'
   when candidates.candidate_count > 0 then 'ambiguous'
   else 'db_only'
  end,
  coalesce(candidates.candidate_count, 0),
  coalesce(candidates.candidate_ids, '[]'::jsonb),
  candidates.best_score,
  resolved.category_id,
  resolved.folder_id,
  false,
  now(),
  now()
 from public.supportos_binds bind
 left join resolved_matches resolved on resolved.database_bind_id = bind.id
 left join lateral (
  select
   count(*)::integer as candidate_count,
   jsonb_agg(candidate.legacy_bind_id order by candidate.score desc, candidate.legacy_bind_id) as candidate_ids,
   max(candidate.score) as best_score
  from candidate_scores candidate
  where candidate.database_bind_id = bind.id
 ) candidates on true
 where bind.owner_id is null
 on conflict (report_key) do update set
  run_id = excluded.run_id,
  side = excluded.side,
  legacy_bind_id = excluded.legacy_bind_id,
  database_bind_id = excluded.database_bind_id,
  status = excluded.status,
  candidate_count = excluded.candidate_count,
  candidate_ids = excluded.candidate_ids,
  best_score = excluded.best_score,
  target_category_id = excluded.target_category_id,
  target_folder_id = excluded.target_folder_id,
  changed = false,
  updated_at = now();

 insert into public.supportos_categories (
  id, owner_id, name, icon, color, order_index
 )
 select
  category->>'i',
  null,
  category->>'n',
  nullif(category->>'k', ''),
  nullif(category->>'x', ''),
  coalesce((category->>'o')::integer, 0)
 from jsonb_array_elements(legacy_data->'c') category
 where nullif(category->>'i', '') is not null
  and nullif(category->>'n', '') is not null
 on conflict (id) do nothing;
 get diagnostics categories_inserted = row_count;

 insert into public.supportos_folders (
  id, owner_id, category_id, parent_id, name, icon, color, order_index
 )
 select
  folder->>'i',
  null,
  coalesce(folder->>'c', ''),
  nullif(folder->>'p', ''),
  folder->>'n',
  nullif(folder->>'k', ''),
  nullif(folder->>'x', ''),
  coalesce((folder->>'o')::integer, 0)
 from jsonb_array_elements(legacy_data->'f') folder
 where nullif(folder->>'i', '') is not null
  and nullif(folder->>'n', '') is not null
 on conflict (id) do nothing;
 get diagnostics folders_inserted = row_count;

 create temporary table changed_database_binds (
  database_bind_id text primary key
 ) on commit drop;

 with changed as (
  update public.supportos_binds bind
  set
   category_id = resolved.category_id,
   folder_id = resolved.folder_id
  from resolved_matches resolved
  where bind.id = resolved.database_bind_id
   and bind.owner_id is null
   and (
    bind.category_id is distinct from resolved.category_id
    or bind.folder_id is distinct from resolved.folder_id
   )
  returning bind.id
 )
 insert into changed_database_binds (database_bind_id)
 select id from changed;

 update public.supportos_legacy_bind_mapping_report report
 set changed = true, updated_at = now()
 from changed_database_binds changed
 where report.run_id = mapping_run
  and report.database_bind_id = changed.database_bind_id;

 select count(*) into binds_after
 from public.supportos_binds;

 if binds_after <> binds_before then
  raise exception 'Legacy mapping changed bind row count: before=%, after=%', binds_before, binds_after;
 end if;

 select count(*) into matched_count from resolved_matches;
 select count(*) into changed_count from changed_database_binds;

 select coalesce(jsonb_object_agg(status, amount), '{}'::jsonb)
 into legacy_summary
 from (
  select status, count(*) as amount
  from public.supportos_legacy_bind_mapping_report
  where run_id = mapping_run and side = 'legacy'
  group by status
 ) counts;

 select coalesce(jsonb_object_agg(status, amount), '{}'::jsonb)
 into database_summary
 from (
  select status, count(*) as amount
  from public.supportos_legacy_bind_mapping_report
  where run_id = mapping_run and side = 'database'
  group by status
 ) counts;

 select coalesce(
  jsonb_agg(
   jsonb_build_object(
    'side', side,
    'legacyBindId', legacy_bind_id,
    'databaseBindId', database_bind_id,
    'candidateIds', candidate_ids,
    'bestScore', best_score
   )
   order by side, coalesce(legacy_bind_id, database_bind_id)
  ),
  '[]'::jsonb
 )
 into ambiguous_report
 from public.supportos_legacy_bind_mapping_report
 where run_id = mapping_run
  and status = 'ambiguous';

 raise notice 'Legacy knowledge mapping summary: legacy=%, database=%, matched=%, changed=%',
  legacy_summary, database_summary, matched_count, changed_count;
 raise notice 'Legacy knowledge structure: source_categories=9, source_folders=19, inserted_categories=%, inserted_folders=%',
  categories_inserted, folders_inserted;
 raise notice 'Legacy knowledge ambiguous mapping report: %', ambiguous_report;
end
$migration$;



